mapper.select:
SELECT cycle.cycle_id FROM hr_appraisal_cycle cycle WHERE cycle.tenant_id = #{tenantId} AND cycle.deleted = 0
AND cycle.cycle_name LIKE CONCAT('%', #{query.keyword}, '%')
AND cycle.status = #{query.status}
AND (
  (cycle.status = 'DRAFT' AND (#{scope.type} = 0 OR cycle.create_by = #{operator})) OR
  EXISTS (SELECT 1 FROM hr_appraisal_result result
    JOIN hr_employee employee ON employee.id = result.employee_id AND employee.tenant_id = result.tenant_id AND employee.deleted = 0
    WHERE result.tenant_id = cycle.tenant_id AND result.cycle_id = cycle.cycle_id

  )
) ORDER BY cycle.cycle_id DESC

SELECT employee.id AS employeeId, employee.name AS employeeName, employee.employee_no AS employeeNo, employee.dept_id AS deptId, employee.position_id AS positionId, position.level_id AS jobLevelId, employee.user_id AS userId, employee.update_time AS updateTime FROM hr_employee employee LEFT JOIN hr_position position ON position.tenant_id = employee.tenant_id AND position.id = employee.position_id WHERE employee.tenant_id = #{tenantId} AND employee.deleted = 0 AND employee.dept_id IS NOT NULL AND employee.employee_status IN ('ACTIVE','REGULAR','PROBATION','INTERN','ON_LEAVE','TRANSFERRED') AND employee.hire_date <= #{today} AND (employee.resign_date IS NULL OR employee.resign_date > #{today})
AND employee.dept_id IN #{identifier}
AND employee.position_id IN #{identifier}
AND position.level_id IN #{identifier}
ORDER BY employee.id
